<div class="wrap superwoo-admin-page"><h1><?php esc_html_e('Cart Recovery','superwoo'); ?></h1><nav class="nav-tab-wrapper"><?php foreach (['overview'=>'Overview','carts'=>'Abandoned Carts','automations'=>'Automations','analytics'=>'Analytics','templates'=>'Templates','settings'=>'Settings'] as $key=>$label) : ?><a class="nav-tab <?php echo $tab===$key?'nav-tab-active':''; ?>" href="<?php echo esc_url(admin_url('admin.php?page=superwoo-cart-recovery&tab='.$key)); ?>"><?php echo esc_html__($label,'superwoo'); ?></a><?php endforeach; ?></nav>
<?php if ($tab==='overview'||$tab==='analytics') : ?><div class="superwoo-recovery-kpis"><p><strong><?php echo esc_html($metrics['active']['count']); ?></strong> Active Carts</p><p><strong><?php echo esc_html($metrics['abandoned']['count']); ?></strong> Abandoned Carts</p><p><strong><?php echo wp_kses_post(wc_price($metrics['abandoned']['revenue'])); ?></strong> Abandoned Revenue</p><p><strong><?php echo esc_html($metrics['recovered']['count']); ?></strong> Recovered Carts</p><p><strong><?php echo wp_kses_post(wc_price($metrics['recovered']['revenue'])); ?></strong> Recovered Revenue</p></div><?php endif; ?>
<?php if ($tab==='carts') : ?><form method="get"><input type="hidden" name="page" value="superwoo-cart-recovery"><input type="hidden" name="tab" value="carts"><input name="s" value="<?php echo esc_attr($_GET['s']??''); ?>" placeholder="Search customer, cart or order"><select name="status"><option value="">All statuses</option><?php foreach(['active','abandoned','recovery_in_progress','recovered','expired'] as $status): ?><option value="<?php echo esc_attr($status); ?>"><?php echo esc_html(ucwords(str_replace('_',' ',$status))); ?></option><?php endforeach; ?></select><button class="button">Filter</button></form><table class="widefat striped"><thead><tr><th>Customer</th><th>Cart Value</th><th>Last Activity</th><th>Abandoned</th><th>Status</th><th>Order</th></tr></thead><tbody><?php foreach($rows['items'] as $cart): ?><tr><td><a href="<?php echo esc_url(admin_url('admin.php?page=superwoo-cart-recovery&cart_id='.(int)$cart['id'])); ?>"><?php echo esc_html(trim($cart['first_name'].' '.$cart['last_name']) ?: ($cart['email'] ?: 'Guest / Anonymous Cart')); ?></a></td><td><?php echo wp_kses_post(wc_price($cart['total'])); ?></td><td><?php echo esc_html(get_date_from_gmt($cart['last_activity_at'])); ?></td><td><?php echo esc_html($cart['abandoned_at'] ? get_date_from_gmt($cart['abandoned_at']) : '—'); ?></td><td><?php echo esc_html(ucwords(str_replace('_',' ',$cart['status']))); ?></td><td><?php echo $cart['order_id'] ? '<a href="'.esc_url(get_edit_post_link($cart['order_id'])).'">#'.esc_html($cart['order_id']).'</a>' : '—'; ?></td></tr><?php endforeach; ?></tbody></table><?php endif; ?></div>
